        .to.emit(sale, "UnsoldTokensRecovered").withArgs(unsold)
        .and.to.changeTokenBalances(ethers, token, [issuer, sale], [unsold, -unsold]);
      expect(await token.balanceOf(issuer.address)).to.equal(SUPPLY - 100n);
